<?php
namespace Tests\Feature;
use App\Models\{User,UmkmDisbursement,UmkmDisbursementAllocation,UmkmEntitlement};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
class UmkmDisbursementCancellationTest extends TestCase { use RefreshDatabase;
 public function test_owner_cancels_requested_and_releases_once():void{[$o,$d,$e,$a]=$this->fixture();$this->actingAs($o)->patch(route('umkm.disbursements.cancel',$d),['reason'=>'Tidak jadi'])->assertRedirect();$this->assertSame('cancelled',$d->fresh()->status);$this->assertNull($d->fresh()->active_request_lock);$this->assertSame('available',$e->fresh()->status);$this->assertNull($a->fresh()->entitlement_reservation_lock);$this->assertDatabaseCount('umkm_disbursement_allocations',1);$this->actingAs($o)->patch(route('umkm.disbursements.cancel',$d),['reason'=>'Retry'])->assertRedirect();$this->assertSame('available',$e->fresh()->status);$this->assertDatabaseHas('umkm_disbursement_events',['umkm_disbursement_id'=>$d->id,'event_type'=>'cancelled']);$this->assertDatabaseHas('umkm_entitlement_events',['umkm_entitlement_id'=>$e->id,'event_type'=>'reservation_released']);}
 public function test_other_owner_and_invalid_states_are_rejected():void{[$o,$d]=$this->fixture();$other=User::factory()->create(['role'=>'penjual']);$this->actingAs($other)->patch(route('umkm.disbursements.cancel',$d),['reason'=>'x'])->assertForbidden();$this->actingAs($o)->patch(route('umkm.disbursements.cancel',$d),[])->assertSessionHasErrors('reason');$d->update(['status'=>'approved']);$this->actingAs($o)->patch(route('umkm.disbursements.cancel',$d),['reason'=>'x'])->assertSessionHasErrors('disbursement');$d->update(['status'=>'paid']);$this->actingAs($o)->patch(route('umkm.disbursements.cancel',$d),['reason'=>'x'])->assertSessionHasErrors('disbursement');}
 private function fixture():array{$o=User::factory()->create(['role'=>'penjual']);$s=$o->umkmStore()->create(['name'=>'T','slug'=>'t'.Str::random(8),'status'=>'approved']);$c=User::factory()->create(['role'=>'pelanggan']);$order=\App\Models\Order::create(['order_number'=>'O'.Str::random(8),'checkout_token'=>(string)Str::uuid(),'user_id'=>$c->id,'fulfillment_method'=>'pickup','recipient_name'=>'x','recipient_phone'=>'1','subtotal'=>1,'shipping_total'=>0,'grand_total'=>1,'payment_status'=>'paid','order_status'=>'completed']);$p=\App\Models\Payment::create(['order_id'=>$order->id,'payment_number'=>'P'.Str::random(8),'payment_method'=>'cash_pickup','amount'=>1,'status'=>'paid']);$so=\App\Models\StoreOrder::create(['order_id'=>$order->id,'umkm_store_id'=>$s->id,'store_order_number'=>'S'.Str::random(8),'store_name_snapshot'=>'T','subtotal'=>1,'shipping_amount'=>0,'total'=>1,'fulfillment_status'=>'completed','commission_status'=>'calculated']);$e=UmkmEntitlement::create(['umkm_store_id'=>$s->id,'order_id'=>$order->id,'store_order_id'=>$so->id,'payment_id'=>$p->id,'source_umkm_amount'=>1,'source_commission_amount'=>0,'source_commission_percentage'=>0,'commission_status_snapshot'=>'calculated','status'=>'reserved','accrued_at'=>now()]);$b=$s->recipientBankAccounts()->create(['bank_name'=>'B','account_holder_name'=>'x','account_number'=>'00123','status'=>'active','active_store_lock'=>'store:'.$s->id,'created_by'=>$o->id,'updated_by'=>$o->id]);$d=UmkmDisbursement::create(['umkm_store_id'=>$s->id,'recipient_bank_account_id'=>$b->id,'recipient_bank_name'=>'B','recipient_account_holder_name'=>'x','recipient_account_number'=>'00123','requested_amount'=>1,'status'=>'requested','active_request_lock'=>'store:'.$s->id,'requested_by'=>$o->id,'requested_at'=>now(),'idempotency_key'=>(string)Str::uuid()]);$a=UmkmDisbursementAllocation::create(['umkm_disbursement_id'=>$d->id,'umkm_entitlement_id'=>$e->id,'amount'=>1,'entitlement_reservation_lock'=>'entitlement:'.$e->id]);return[$o,$d,$e,$a];}}
